<?php $token=htmlspecialchars((string)$csrf,ENT_QUOTES,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f172a"><link rel="stylesheet" href="/assets/css/app.css"><style>body{background:#f5f7fb}.page{max-width:1100px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:22px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:22px;box-shadow:0 8px 30px rgba(15,23,42,.06)}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:700;font-size:13px;margin-bottom:6px}input,select{width:100%;padding:12px 13px;border:1px solid #dbe1ea;border-radius:10px;background:#fff}button,.btn{display:inline-block;border:0;border-radius:10px;padding:12px 16px;background:#2563eb;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.secondary{background:#eef2f7;color:#0f172a}.customer-results{display:grid;gap:8px;margin-top:8px}.customer{padding:12px;border:1px solid #e5e7eb;border-radius:10px;cursor:pointer}.customer:hover{background:#f8fafc}.invoice{padding:13px;border:1px solid #e5e7eb;border-radius:10px;margin-top:8px}.muted{color:#64748b}.error{color:#b91c1c;margin-top:10px}.success{color:#047857;margin-top:10px}@media(max-width:760px){.grid,.form-grid{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}}</style><title>Collection · ISPLUKA</title></head><body><main class="page"><div class="top"><div><h1>Collection</h1><p class="muted">Collect a customer payment and settle the selected invoice.</p></div><a class="btn secondary" href="/">Dashboard</a></div><div class="grid"><section class="card"><h2>1. Select Customer</h2><input id="search" placeholder="Name, phone or customer code" autocomplete="off"><div id="customers" class="customer-results"></div><div id="selected" class="muted"></div></section><section class="card"><h2>2. Payment</h2><form id="form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="customer_id" id="customer_id"><div id="invoices"><p class="muted">Select a customer first.</p></div><div class="form-grid" style="margin-top:14px"><div><label>Amount</label><input name="amount" id="amount" type="number" min="1" step="0.01" required></div><div><label>Method</label><select name="method"><option value="cash">Cash</option><option value="bkash">bKash</option><option value="nagad">Nagad</option><option value="bank">Bank</option><option value="card">Card</option><option value="other">Other</option></select></div></div><div style="margin-top:14px"><label>Reference (optional)</label><input name="reference" placeholder="Auto-generated if blank"></div><button style="margin-top:16px" type="submit">Collect Payment</button><div id="message"></div></form></section></div></main><script>const q=document.getElementById('search'),list=document.getElementById('customers'),cid=document.getElementById('customer_id'),sel=document.getElementById('selected'),inv=document.getElementById('invoices'),amount=document.getElementById('amount'),msg=document.getElementById('message');let timer; q.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const s=q.value.trim();if(!s){list.innerHTML='';return}const r=await fetch('/api/customers?search='+encodeURIComponent(s)+'&per_page=8');const j=await r.json();list.innerHTML=(j.data?.items||[]).map(c=>`<div class="customer" data-id="${c.id}"><strong>${esc(c.name)}</strong><br><small>${esc(c.customer_code)} · ${esc(c.phone||'No phone')}</small></div>`).join('')||'<p class="muted">No customer found.</p>';list.querySelectorAll('.customer').forEach(x=>x.onclick=()=>selectCustomer(x.dataset.id,x.textContent.trim()))},250)});async function selectCustomer(id,text){cid.value=id;sel.innerHTML='<p><strong>Selected:</strong> '+esc(text)+'</p>';const r=await fetch('/api/collection/invoices?customer_id='+id);const j=await r.json();const rows=j.data||[];inv.innerHTML=rows.map((i,n)=>`<label class="invoice"><input type="radio" name="invoice_id" value="${i.id}" data-due="${i.due}" ${n===0?'checked':''}> <strong>${esc(i.invoice_number)}</strong> · Due ৳${Number(i.due).toLocaleString()}</label>`).join('')||'<p class="muted">No unpaid invoice found.</p>';const first=rows[0];if(first)amount.value=Number(first.due);inv.querySelectorAll('input').forEach(x=>x.onchange=()=>amount.value=Number(x.dataset.due))}document.getElementById('form').onsubmit=async e=>{e.preventDefault();msg.textContent='Saving…';msg.className='muted';const r=await fetch('/api/collection',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(e.target))});const j=await r.json();if(!r.ok){msg.textContent=j.error?.message||'Unable to collect payment.';msg.className='error';return}msg.textContent='Payment collected: '+j.data.reference+' · ৳'+Number(j.data.amount).toLocaleString();msg.className='success';e.target.reset();cid.value='';sel.innerHTML='';inv.innerHTML='<p class="muted">Select a customer first.</p>'};function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}</script></body></html>